INSERT INTO quiz_questions (chapter_id, position, prompt, explanation) VALUES (8, 1, 'An email from ''IT Support'' asks you to confirm your password within 1 hour. What do you do?', 'Urgency plus a credential request is the classic phishing pattern. Report it; IT never asks for passwords.');
INSERT INTO quiz_options (question_id, position, text, correct) VALUES (@q, 1, 'Reply with your password', FALSE);
INSERT INTO quiz_options (question_id, position, text, correct) VALUES (@q, 2, 'Click the link and log in', FALSE);
INSERT INTO quiz_options (question_id, position, text, correct) VALUES (@q, 3, 'Report it with the Report Phishing button', TRUE);
INSERT INTO quiz_questions (chapter_id, position, prompt, explanation) VALUES (8, 2, 'Which sender address is most suspicious for a message claiming to be from your company?', 'Look-alike domains swap letters or add words to the real domain.');
INSERT INTO quiz_options (question_id, position, text, correct) VALUES (@q, 1, 'it@yourcompany.com', FALSE);
INSERT INTO quiz_options (question_id, position, text, correct) VALUES (@q, 2, 'it@yourcompany-support.net', TRUE);
INSERT INTO quiz_options (question_id, position, text, correct) VALUES (@q, 3, 'noreply@yourcompany.com', FALSE);
INSERT INTO quiz_questions (chapter_id, position, prompt, explanation) VALUES (8, 3, 'You opened an unexpected attachment and your laptop is acting strangely. First step?', 'Disconnecting limits spread; then report immediately.');
INSERT INTO quiz_options (question_id, position, text, correct) VALUES (@q, 1, 'Restart and hope', FALSE);
INSERT INTO quiz_options (question_id, position, text, correct) VALUES (@q, 2, 'Disconnect from the network and contact security', TRUE);
INSERT INTO quiz_options (question_id, position, text, correct) VALUES (@q, 3, 'Delete the email', FALSE);
