INSERT INTO quiz_questions (chapter_id, position, prompt, explanation) VALUES (13, 1, 'Which index best serves: WHERE user_id = ? ORDER BY created_at DESC LIMIT 20?', 'A composite index with the equality column first lets MySQL read the rows already in order.');
INSERT INTO quiz_options (question_id, position, text, correct) VALUES (@q, 1, '(created_at)', FALSE);
INSERT INTO quiz_options (question_id, position, text, correct) VALUES (@q, 2, '(user_id, created_at)', TRUE);
INSERT INTO quiz_options (question_id, position, text, correct) VALUES (@q, 3, '(created_at, user_id)', FALSE);
INSERT INTO quiz_questions (chapter_id, position, prompt, explanation) VALUES (13, 2, 'In EXPLAIN output, what does ''Using filesort'' usually indicate?', 'MySQL had to sort rows after reading them instead of using an index order.');
INSERT INTO quiz_options (question_id, position, text, correct) VALUES (@q, 1, 'An extra sort step', TRUE);
